## 2. KNOWLEDGE GRAPH SCHEMA

```cypher
CREATE CONSTRAINT party_id IF NOT EXISTS FOR (p:Party) REQUIRE p.id IS UNIQUE;
CREATE CONSTRAINT claim_id IF NOT EXISTS FOR (c:Claim) REQUIRE c.id IS UNIQUE;
CREATE CONSTRAINT policy_id IF NOT EXISTS FOR (po:Policy) REQUIRE po.id IS UNIQUE;

CREATE INDEX claim_filed FOR (c:Claim) ON (c.filed_date);

// Party:   {id, name, type:CLAIMANT|PROVIDER|WITNESS, address, phone, fraud_score}
// Claim:   {id, claimed_amount, filed_date, status:PENDING|APPROVED|DENIED|SETTLED, siu_score:0-100}
// Policy:  {id, type:AUTO|HOME|HEALTH, premium, coverage_limit, effective_date, expiration_date}

// Relationships
// (c:Claim)-[:FILED_BY]->(p:Party)
// (p:Party)-[:TREATED_AT]->(provider:Party {type:'PROVIDER'})
// (p:Party)-[:SHARES_ADDRESS]->(p2:Party)
// (p:Party)-[:SHARES_PHONE]->(p2:Party)

CALL gds.graph.project('insurance_graph', ['Party','Claim'], {
  FILED_BY:{orientation:'NATURAL'},
  TREATED_AT:{orientation:'NATURAL'},
  REPRESENTED_BY:{orientation:'NATURAL'},
  SHARES_ADDRESS:{orientation:'UNDIRECTED'},
  SHARES_PHONE:{orientation:'UNDIRECTED'}
});
```
